array.string:
set -a; . "$HOME/.config/jarvis/env"; set +a
J="$HOME/.config/jarvis"; LOCK="$J/poll.lock"; REPO="$HOME/github.com/tazgreenwood/private-dotfiles"
t() { date -u +%Y-%m-%dT%H:%M:%SZ; }
mkdir "$LOCK" 2>/dev/null || { echo "$(t) skip: previous tick still running"; exit 0; }
trap 'rmdir "$LOCK" 2>/dev/null' EXIT
[ -n "$SLACK_BOT_TOKEN" ] || { echo "$(t) fatal: SLACK_BOT_TOKEN unset in $J/env"; exit 1; }
[ -n "$CLAUDE_CODE_OAUTH_TOKEN" ] || { echo "$(t) fatal: CLAUDE_CODE_OAUTH_TOKEN unset in $J/env"; exit 1; }
R="$REPO/claude/mcp/server/registry"
RES=$(printf '%s\n%s\n' '{"jsonrpc":"2.0","id":1,"method":"initialize","params":{"protocolVersion":"2024-11-05","capabilities":{},"clientInfo":{"name":"jarvis-poll","version":"1"}}}' '{"jsonrpc":"2.0","id":2,"method":"tools/call","params":{"name":"registry_get_resources","arguments":{"name":"private-dotfiles","category":"slack"}}}' | "$R" 2>/dev/null | tail -1 | jq -r '.result.content[0].text // empty')
CH=$(printf '%s' "$RES" | jq -r '.resources.slack.jarvis_channel // empty')
WHO=$(printf '%s' "$RES" | jq -r '.resources.slack.jarvis_user_id // empty')
[ -n "$CH" ] && [ -n "$WHO" ] || { echo "$(t) fatal: registry gave no jarvis_channel/jarvis_user_id"; exit 1; }
H=$(curl -sS --max-time 30 "https://slack.com/api/conversations.history?channel=$CH&limit=30" -H "Authorization: Bearer $SLACK_BOT_TOKEN")
[ "$(printf '%s' "$H" | jq -r '.ok')" = "true" ] || { echo "$(t) fatal: slack read failed: $(printf '%s' "$H" | jq -r '.error')"; exit 1; }
N=$(printf '%s' "$H" | jq --arg u "$WHO" '[.messages[] | select(.user == $u or ((.reply_count // 0) > 0))] | length')
[ "$N" = "0" ] && { echo "$(t) tick: quiet, no agent spawned, cost 0.00"; exit 0; }
echo "$(t) tick: $N candidate(s), escalating to planning run"
cd "$REPO" || exit 1
O=$(claude -p '/jarvis poll' --permission-mode default --max-turns 80 --output-format json 2>&1)
echo "$(t) run: subtype=$(printf '%s' "$O" | jq -r '.subtype // "unparsed"' 2>/dev/null) cost=$(printf '%s' "$O" | jq -r '.total_cost_usd // "?"' 2>/dev/null)"
